    'BYSETPOS=1 (first Monday of year)',
    assert_occurrences_equal(
        'First Monday of year',
        ARRAY[
            '2025-01-06 00:00:00'::TIMESTAMP,
            '2026-01-05 00:00:00'::TIMESTAMP,
            '2027-01-04 00:00:00'::TIMESTAMP
        ],
        (SELECT array_agg(occurrence ORDER BY occurrence) FROM rrule."all"('FREQ=YEARLY;BYDAY=MO;BYSETPOS=1;COUNT=3', '2025-01-01'::TIMESTAMP) AS occurrence)
    )
);

-- Test 4.2: Last Monday of each year (BYSETPOS=-1)
-- 2025: Dec 29, 2026: Dec 28, 2027: Dec 27
INSERT INTO bysetpos_test_results (test_category, test_name, status)
VALUES (
    'YEARLY BYSETPOS',
    'BYSETPOS=-1 (last Monday of year)',
    assert_occurrences_equal(
        'Last Monday of year',
        ARRAY[
            '2025-12-29 00:00:00'::TIMESTAMP,
            '2026-12-28 00:00:00'::TIMESTAMP,
            '2027-12-27 00:00:00'::TIMESTAMP
        ],
        (SELECT array_agg(occurrence ORDER BY occurrence) FROM rrule."all"('FREQ=YEARLY;BYDAY=MO;BYSETPOS=-1;COUNT=3', '2025-01-01'::TIMESTAMP) AS occurrence)
    )
);

------------------------------------------------------------------------------------------------------
-- Print Test Results
------------------------------------------------------------------------------------------------------
\echo ''
\echo '==================================================================='
\echo 'Test Results'
\echo '==================================================================='
\echo ''

SELECT
    test_category,
    test_name,
    CASE
        WHEN status LIKE 'PASS%' THEN '✓ ' || test_name
        ELSE '✗ ' || test_name || ' - ' || status
    END AS result
FROM bysetpos_test_results
ORDER BY test_category, test_name;

-- Check if all tests passed
DO $$
DECLARE
    failed_count INT;
    total_count INT;
BEGIN
    SELECT COUNT(*) INTO failed_count
    FROM bysetpos_test_results
    WHERE status NOT LIKE 'PASS%';

    SELECT COUNT(*) INTO total_count
    FROM bysetpos_test_results;

    RAISE NOTICE '';
    RAISE NOTICE '===================================================================';
    IF failed_count = 0 THEN
        RAISE NOTICE 'BYSETPOS Filtering Tests: % / % PASSED', total_count, total_count;
        RAISE NOTICE '===================================================================';
    ELSE
        RAISE NOTICE 'BYSETPOS Filtering Tests: % / % FAILED', failed_count, total_count;
        RAISE NOTICE '===================================================================';
        RAISE EXCEPTION 'BYSETPOS filtering tests failed';
    END IF;
END $$;

ROLLBACK;
